public Invoice duplicate(LocalDate issueDate, LocalDate dueDate) {
    Invoice copy = draft(clientId, clientTaxExempt, clientTaxExemptUntil, clientPricesIncludeTax, regionTaxRate, regionRateChanges, regionRoundsDown, outOfRegionTaxNumber, currency(), issueDate, dueDate);
    copy.supplyRegion = supplyRegion;
    copy.discountPct = discountPct;
    copy.discountAmount = discountAmount;
    copy.discountCap = discountCap;
    copy.discountReason = discountReason;
    copy.surchargePct = surchargePct;
    lines.forEach(line -> copy.addLine(line.copy()));
    return copy;
}

/**
 * The next period's draft of this recurring invoice for the same client, issued and due on the given dates: a copy of
 * each line with a service period, moved to the whole calendar month after the latest period end on the invoice (lines
 * without a period are one-off charges and are not copied), with this invoice's percentage discount and surcharge.
 * The period stops on the end date when it falls inside that month (and is prorated as usual).
 * The draft is recurring too, keeps the end date and plan date and remembers it was generated from this invoice.
 * When the period starts on or after the next anniversary of the plan date, each typed unit price (not one priced from
 * the rates) goes up by the client's yearly percentage, rounded half up to the cent, and the draft's plan date moves on a year.
 */
public Invoice nextPeriod(LocalDate issueDate, LocalDate dueDate, BigDecimal upliftPct) {
    Invoice next = draft(clientId, clientTaxExempt, clientTaxExemptUntil, clientPricesIncludeTax, regionTaxRate, regionRateChanges, regionRoundsDown, outOfRegionTaxNumber, currency(), issueDate, dueDate);
    next.supplyRegion = supplyRegion;
    next.discountPct = discountPct;
    next.surchargePct = surchargePct;
    next.recurring = true;
    next.recurringFrom = id;
    next.recurUntil = recurUntil;
    next.recurringSince = recurringSince;
    LocalDate start = nextPeriodStart();
    boolean rise = recurringSince != null && !start.isBefore(recurringSince.plusYears(1));
    if (rise) {
        next.recurringSince = recurringSince.plusYears(1);
    }
    LocalDate end = start.withDayOfMonth(start.lengthOfMonth());
    if (recurUntil != null && recurUntil.isBefore(end)) {
        end = recurUntil;
    }
    for (InvoiceLine line : lines) {
        if (line.hasPeriod()) {
            InvoiceLine copy = line.copy();
            copy.setPeriod(start, end);
            if (rise && upliftPct != null && upliftPct.signum() > 0) {
                copy.raisePrice(upliftPct);
            }
            next.addLine(copy);
        }
    }
    return next;
}

/**
 * The next progress claim of this invoice: a draft for the same client, issued and due on the given dates, with a claim copy
 * of each line billed by progress (see {@link InvoiceLine#claimCopy}) — so nothing more is billed until its percentage is
 * raised — and this invoice's percentage discount and surcharge. Lines billed whole are not copied. It remembers it was
 * claimed from this invoice.
 */
public Invoice nextClaim(LocalDate issueDate, LocalDate dueDate) {
    Invoice next = draft(clientId, clientTaxExempt, clientTaxExemptUntil, clientPricesIncludeTax, regionTaxRate, regionRateChanges, regionRoundsDown, outOfRegionTaxNumber, currency(), issueDate, dueDate);
    next.supplyRegion = supplyRegion;
    next.discountPct = discountPct;
    next.surchargePct = surchargePct;
    next.claimFrom = id;
    lines.stream().filter(InvoiceLine::isProgress).forEach(line -> next.addLine(line.claimCopy()));
    return next;
}

/**
 * The corrected replacement of this rebilled invoice: a draft for the same client, issued and due on the given dates,
 * with copies of its lines, its percentage discount, surcharge and purchase order number, worked out afresh. It
 * remembers which invoice it replaces. It carries on what was going on with this invoice: an open dispute (from the
 * same day, over the same lines), its milestones (with the days they were reached and disputed) and its recurring plan.
 * When it has had reminders they move to the replacement, which keeps this invoice's due date (see
 * {@link #carriesChasing}), so the chasing carries on where it was.
 */
public Invoice rebill(LocalDate issueDate, LocalDate dueDate) {
    boolean chased = !reminders.isEmpty();
    Invoice next = draft(clientId, clientTaxExempt, clientTaxExemptUntil, clientPricesIncludeTax, regionTaxRate, regionRateChanges, regionRoundsDown, outOfRegionTaxNumber, currency(), issueDate, chased ? this.dueDate : dueDate);
    if (chased) {
        next.reminders.addAll(reminders);
        reminders.clear();
    }
    next.supplyRegion = supplyRegion;
    next.discountPct = discountPct;
    next.surchargePct = surchargePct;
    next.poNumber = poNumber;
    next.replaces = id;
    boolean disputed = isInvoiceDisputed();
    lines.forEach(line -> {
        InvoiceLine copy = line.copy();
        copy.setDisputed(disputed && line.isDisputed());
        next.addLine(copy);
    });
    if (disputed) {
        next.disputedOn = disputedOn;
    }
    milestones.forEach(m -> next.addMilestone(m.carryOver()));
    next.recurring = recurring;
    next.recurringSince = recurringSince;
    next.recurUntil = recurUntil;
    return next;
}

/**
 * Takes the rebilled invoice's open states off it, now its replacement carries them: its dispute (its milestones'
 * included) is resolved on the day and it stops recurring.
 */
public void handOver(LocalDate on) {
    if (isDisputed()) {
        resolveDispute(on);
    }
    this.recurring = false;
}

/**
 * Approves the draft at the grand total on the day with as many approvals as it needs: a replacement for no more than
 * what the invoice it replaces was sent for is approved already.
 */
public void approveInFull(BigDecimal total, LocalDate on, BigDecimal taxRate) {
    this.approvals = approvalsRequired(taxRate);
    this.approvedTotal = total;
    this.approvedOn = on;
}

/**
 * A draft credit note for exactly what this sent invoice is worth, issued on the given date: a credit copy of each
 * of its lines, with its grand total and tax at the tax rate (those it was sent with, when kept) as its own.
 */
public Invoice creditNoteInFull(LocalDate issueDate, BigDecimal taxRate) {
    Invoice note = creditNote(issueDate);
    lines.forEach(line -> note.addLine(line.creditCopy()));
    note.sentTotal = total(taxRate);
    note.sentTax = tax(taxRate);
    return note;
}

/** Notes that the invoice was rebilled on the day. */
public void markRebilled(LocalDate on) {
    this.rebilledOn = on;
}

/** The day the invoice was rebilled; null when it was not. */
public LocalDate getRebilledOn() {
    return rebilledOn;
}

/** The id of the rebilled invoice this one replaces; null when it replaces none. */
public Long getReplaces() {
    return replaces;
}

/** The id of the invoice that replaces this rebilled one; null when none does. */
public Long getReplacedBy() {
    return replacedBy;
}

/** Whether any line is billed by progress. */
public boolean hasProgressLines() {
    return lines.stream().anyMatch(InvoiceLine::isProgress);
}

/** The id of the sent invoice this draft was claimed from; null when it was not. */
public Long getClaimFrom() {
    return claimFrom;
}

/** The first day of the next period: the first of the month after the latest period end. */
public LocalDate nextPeriodStart() {
    return latestPeriodEnd().plusMonths(1).withDayOfMonth(1);
}

/** The latest service period end of the invoice's lines; null when no line has a period. */
public LocalDate latestPeriodEnd() {
    return lines.stream().filter(InvoiceLine::hasPeriod).map(InvoiceLine::getPeriodEnd)
            .max(LocalDate::compareTo).orElse(null);
}

/** Whether the invoice repeats every period. */
public boolean isRecurring() {
    return recurring;
}

/**
 * Makes the invoice recurring, or not. When first made recurring its plan begins on its first period's start
 * (the earliest service period start of its lines).
 */
public void setRecurring(boolean recurring) {
    this.recurring = recurring;
    if (recurring && recurringSince == null) {
